function isErrnoException(error: unknown): error is NodeJS.ErrnoException {
    return error instanceof Error && "code" in error
}

try {
    await readFile("config.json", "utf8")
} catch (error) {
    if (isErrnoException(error) && error.code === "ENOENT") console.log("config.json yo'q — standart qiymatlar")
    else throw error   // kutilmagan xatoni yutib yubormang
}

async function writeAtomic(path: string, data: string): Promise<void> {
    const tmp = `${path}.${process.pid}.tmp`
    await writeFile(tmp, data, "utf8")
    await rename(tmp, path)   // bir lahzada almashadi
}

type Settings = { theme: "light" | "dark"; fontSize: number }

async function loadSettings(path: string): Promise<Settings> {
    const data: unknown = JSON.parse(await readFile(path, "utf8"))
    const s = (typeof data === "object" && data !== null ? data : {}) as Record<string, unknown>
    return {
        theme: s.theme === "dark" ? "dark" : "light",
        fontSize: typeof s.fontSize === "number" ? s.fontSize : 14,   // noto'g'ri bo'lsa — standart qiymat
    }
}

