import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"

interface Settings {
    theme: string
    fontSize: number
}

async function saveSettings(file: string, settings: Settings): Promise<void> {
    await writeFile(file, JSON.stringify(settings, null, 2), "utf-8")
}

async function loadSettings(file: string): Promise<Settings> {
    const raw = await readFile(file, "utf-8")
    return JSON.parse(raw) as Settings
}

async function main() {
    const dir = await mkdtemp(join(tmpdir(), "settings-"))
    const file = join(dir, "settings.json")
    await saveSettings(file, { theme: "dark", fontSize: 14 })
    const settings = await loadSettings(file)
    console.log(settings.theme, settings.fontSize)
    await rm(dir, { recursive: true })
}
main()

import { readFile } from "node:fs/promises"

async function readConfig(path: string): Promise<string | null> {
    try {
        return await readFile(path, "utf-8")
    } catch (error) {
        const err = error as NodeJS.ErrnoException
        if (err.code === "ENOENT") {
            console.log("Fayl topilmadi:", path)
        } else {
            console.log("Kutilmagan xato:", err.message)
        }
        return null
    }
}

readConfig("config.json").then(config => console.log(config ?? "standart sozlamalar ishlatiladi"))

