import { readFileSync } from "node:fs"

function safeRead(path: string): { ok: true; content: string } | { ok: false; error: string } {
    try {
        return { ok: true, content: readFileSync(path, "utf-8") }
    } catch (error) {
        const err = error as NodeJS.ErrnoException
        const messages: Record<string, string> = {
            ENOENT: "Fayl topilmadi",
            EACCES: "Ruxsat yo'q",
            EISDIR: "Bu papka, fayl emas",
        }
        return { ok: false, error: messages[err.code ?? ""] ?? err.message }
    }
}

const result = safeRead("mavjud-emas.txt")
console.log(result.ok ? result.content : `Xato: ${result.error}`)

const dirResult = safeRead(".")
console.log(dirResult.ok ? "o'qildi" : `Xato: ${dirResult.error}`)

