import { createReadStream, createWriteStream, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { pipeline } from "node:stream/promises"
import { Transform } from "node:stream"

const dir = mkdtempSync(join(tmpdir(), "upper-"))
const source = join(dir, "kirish.txt")
const target = join(dir, "chiqish.txt")
writeFileSync(source, "salom dunyo\nfayl oqimi\n")

