async function withLock<T>(lockFile: string, task: () => Promise<T>): Promise<T | "band"> {
    try {
        await writeFile(lockFile, "lock", { flag: "wx" })   // faqat yangi bo'lsa yaratiladi
    } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "EEXIST") return "band"
        throw error
    }
    try {
        return await task()
    } finally {
        await rm(lockFile)   // qulfni bo'shatamiz
    }
}

