function tree(d: string, pre = ""): string[] {
    const es = readdirSync(d, { withFileTypes: true }).toSorted((a, b) => a.name.localeCompare(b.name))
    return es.flatMap((e, i) => {
        const last = i === es.length - 1, line = `${pre}${last ? "└── " : "├── "}${e.name}`
        return e.isDirectory() ? [line, ...tree(join(d, e.name), pre + (last ? "    " : "│   "))] : [line]
    })
}
